        for i, j in edges:
            graph[i].append(j)
            graph[j].append(i)

        parent_arr = [-1] * n
        level_arr = [-1] * n

        stack = [0]
        parent_arr[0] = -1
        level_arr[0] = 0
        while stack:
            node = stack.pop()
            for neighbor in graph[node]:
                if neighbor == parent_arr[node]:
                    continue
                parent_arr[neighbor] = node
                level_arr[neighbor] = level_arr[node] + 1
                stack.append(neighbor)

        def lca(a, b):
            if level_arr[a] < level_arr[b]:
                a, b = b, a
            d = level_arr[a] - level_arr[b]
            while d:
                a = parent_arr[a]
                d -= 1
            if a == b:
                return a
            while a != b:
                a = parent_arr[a]
                b = parent_arr[b]
