class Solution:
    def dp(self, i, s, prev, k, ct, n, dct):
        if k < 0:
            return float('inf')
        if i >= n:
            if ct == 0:
                return 0
            if ct == 1:
                return 1
            else:
                return len(str(ct)) + 1

        key = (i, prev, ct, k)
        if key in dct:
            return dct[key]

        if s[i] == prev:
            inc = self.dp(i+1, s, prev, k, ct+1, n, dct)
            exc = self.dp(i+1, s, prev, k-1, ct, n, dct) if k > 0 else float('inf')
        else:
            if ct > 1:
                x = len(str(ct)) + 1
            elif ct == 1:
                x = 1
            else:
                x = 0
            inc = x + self.dp(i+1, s, s[i], k, 1, n, dct)
            exc = self.dp(i+1, s, prev, k-1, ct, n, dct) if k > 0 else float('inf')

        res = min(inc, exc)
        dct[key] = res
        return res

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        return self.dp(0, s, "", k, 0, n, {})

